async function foldArchive(chunks, initial, reduce) {
  const iterator = chunks[Symbol.asyncIterator]();
  let closed = false;

  const closeIterator = async () => {
    if (closed) return;
    closed = true;

    try {
      const returnMethod = iterator.return;
      if (typeof returnMethod === "function") {
        try {
          await returnMethod.call(iterator);
        } catch (_) {
          // Cleanup failures are ignored.
        }
      }
    } catch (_) {
      // Cleanup failures are ignored.
    }
  };

  const decoder = new TextDecoder("utf-8");
  let state = initial;
  let physicalLine = 1;
  let recordIndex = 0;
  let lineParts = [];

  const processLine = async (line) => {
    if (line.endsWith("\r")) {
      line = line.slice(0, -1);
    }

    if (line.length === 0) return false;

    let value;
    try {
      value = JSON.parse(line);
    } catch (_) {
      return false;
    }

    const result = await reduce(state, value, {
      physicalLine,
      recordIndex
    });

    state = result.state;
    recordIndex += 1;
    return result.done === true;
  };

  const processText = async (text) => {
    let start = 0;

    while (true) {
      const newline = text.indexOf("\n", start);
      if (newline === -1) break;

      lineParts.push(text.slice(start, newline));
      const line = lineParts.join("");
      lineParts = [];

      const done = await processLine(line);
      physicalLine += 1;

      if (done) return true;
      start = newline + 1;
    }

    if (start < text.length) {
      lineParts.push(text.slice(start));
    }

    return false;
  };

  try {
    while (true) {
      const step = await iterator.next();

      if (step.done) {
        const tail = decoder.decode();

        if (await processText(tail)) {
          return state;
        }

        if (lineParts.length > 0) {
          const line = lineParts.join("");
          lineParts = [];
          await processLine(line);
        }

        return state;
      }

      const text = decoder.decode(step.value, { stream: true });

      if (await processText(text)) {
        await closeIterator();
        return state;
      }
    }
  } catch (error) {
    await closeIterator();
    throw error;
  }
}
